const SHOW_ADVANCE_SETTLEMENT_TOOL=false;
const e=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
const m=v=>(Number(v)||0).toLocaleString("th-TH");
const handoffDate=v=>{const s=String(v||"").trim();return s?s.replace(/^([^T\s]+)[T\s].*$/,"$1"):"-";};
const date=v=>{const x=v instanceof Date?v:(v?new Date(v):new Date());return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,"0")}-${String(x.getDate()).padStart(2,"0")}`;};
const today=()=>date(); const product=x=>[x?.name||x?.product,x?.size,x?.pattern].filter(Boolean).join(" · ");
