// on the device by WageCore, the same code GAS runs, and the snapshot is
// revalidated in the background. Without one, the server path below runs
// and a snapshot is fetched for next time.
function viewingWage(root){return S.tab==="wage"&&root?.isConnected&&root.dataset.route==="workshop";}
function wageIdle(){return !S.saving&&!document.querySelector(".pwa-workshop-modal,.pwa-workshop-dialog");}
function computeWageLocally(key){
  const [start,end]=key.split("|");
  S.wages[key]=computeLocalWage(start,end);S.wageLoadedAt[key]=Date.now();S.wageLocal[key]=true;
  delete S.wageErrors[key];
  if(S.localNeedsSync)S.wageStale[key]=true;else delete S.wageStale[key];
  return S.wages[key];
}
// After a newer snapshot arrives, update cached attendance views. The open
// daily page is left alone: its unsaved status toggles live only in the DOM.
function refreshLocalAttendance(root){
  if(!localAttendanceReady(S.owner))return;
  Object.keys(S.months).forEach(key=>{const [y,mo]=key.split("-").map(Number);S.months[key]=localAttendanceMonth(y,mo);S.monthFetchedAt[key]=Date.now();});
  Object.keys(S.daily).forEach(day=>{if(!(S.tab==="daily"&&day===S.day))S.daily[day]=localAttendanceByDate(day);});
  if(S.tab==="monthly"&&root?.isConnected&&root.dataset.route==="workshop"&&!S.attEdit&&wageIdle())render(root);
}
function syncLocalWages(root){
  if(!localWageSupported()||!S.owner)return;
  const token=S.token,force=S.localNeedsSync;
  S.localSyncing=true;
  if(viewingWage(root))document.body.classList.add("pwa-refreshing");
  syncLocalWage(S.api,token,S.owner,{force}).then(({changed})=>{
    if(token!==S.token)return;
    if(force)S.localNeedsSync=false;
    if(changed||force)refreshLocalAttendance(root);
    if(!changed&&!force&&Object.keys(S.wageLocal).length)return;
    const keys=new Set([...Object.keys(S.wages),S.wageKey].filter(Boolean));
    keys.forEach(computeWageLocally);
    if(viewingWage(root)&&wageIdle())render(root);
  }).catch(()=>{}).finally(()=>{
    S.localSyncing=false;
    if(!Object.keys(S.wageStale).length)document.body.classList.remove("pwa-refreshing");
  });
}
function loadWagePeriod(root,key,{prefetch=false,mode="half"}={}){
  if(localWageReady(S.owner)){
    const value=computeWageLocally(key);
    if(!prefetch){if(viewingWage(root)&&S.wageKey===key&&wageIdle())render(root);syncLocalWages(root);}
    return Promise.resolve(value);
  }
  if(!prefetch&&localWageSupported()&&S.owner&&!S.localSyncing)syncLocalWages(root);
  // A period shown within the last 20s is used as is. Older figures (viewed
  // or prefetched) are painted at once and revalidated; wage actions wait
  // for the fresh figures (see wageActionBlocked). Writes still clear all
  // periods through invalidateWages.
  const cached=S.wages[key],fresh=cached&&Date.now()-(S.wageLoadedAt[key]||0)<20_000;
  if(fresh){if(!prefetch)queuePreviousWage(root,key,mode);return Promise.resolve(cached);}
  if(S.wageRequests[key]){
    if(!prefetch)return S.wageRequests[key].then(value=>{if(value&&S.tab==="wage"&&S.wageKey===key)queuePreviousWage(root,key,mode);return value;});
    return S.wageRequests[key];
  }
  const [start,end]=key.split("|"),token=S.token,generation=S.wageGeneration;
  const viewing=()=>S.tab==="wage"&&S.wageKey===key&&root?.isConnected&&root.dataset.route==="workshop";
  delete S.wageErrors[key];
  if(cached){S.wageStale[key]=true;if(viewing())document.body.classList.add("pwa-refreshing");}
  const request=S.api.workshopWageSummary(token,start,end).then(reply=>{
    if(!reply.ok)throw Error(reply.message||"โหลดสรุปค่าแรงไม่สำเร็จ");
    if(token!==S.token||generation!==S.wageGeneration)return null;
    S.wages[key]=reply.result||{};S.wageLoadedAt[key]=Date.now();delete S.wageStale[key];
    if(viewing()&&!S.saving&&!document.querySelector(".pwa-workshop-modal,.pwa-workshop-dialog"))render(root);
    if(!prefetch&&S.tab==="wage"&&S.wageKey===key)queuePreviousWage(root,key,mode);
    return S.wages[key];
  }).catch(error=>{
    if(generation===S.wageGeneration){delete S.wageStale[key];if(!S.wages[key]){S.wageErrors[key]=String(error.message||error);if(viewing())render(root);}}
    if(token===S.token&&generation===S.wageGeneration&&(!prefetch||(S.tab==="wage"&&S.wageKey===key)))S.toast(`โหลดสรุปค่าแรงไม่สำเร็จ: ${error.message||error}`);
    return null;
  }).finally(()=>{if(S.wageRequests[key]===request)delete S.wageRequests[key];if(!Object.keys(S.wageStale).length)document.body.classList.remove("pwa-refreshing");});
  S.wageRequests[key]=request;
  return request;
}
// Printing, confirming or settling from figures that are still being
// revalidated could use a superseded total; wait for the fresh summary.
function wageActionBlocked(a){
  if(!["printWage","confirmWagePrint","printAllWages","confirmWages","submitWageConfirm","openAdvanceSettlement","saveAdvanceSettlement","editClosedWage","saveClosedWage"].includes(a)||!(S.wageStale[S.wageKey]||S.localSyncing))return false;
  S.toast("กำลังอัปเดตตัวเลขค่าแรงล่าสุด รอสักครู่แล้วกดอีกครั้ง");
  return true;
}
function loadWage(root){
  if(!S.localLoaded&&localWageSupported()&&S.owner){S.localLoaded=true;return loadLocalWage(S.owner).catch(()=>null).then(()=>loadWage(root));}
  const mode=S.wageMode==="person"?(S.personPeriod||"half"):S.wageMode;
  const ps=periods(mode),key=S.wageKey||`${ps[0][0]}|${ps[0][1]}`;
  S.wageKey=key;
  return loadWagePeriod(root,key,{mode});
}
/* Override the first-pass compact views with the same information hierarchy as GAS. */
