  if(auto)return `<section class="pwa-firing-wrap"><div class="pwa-workshop-title"><h2>🔥 คิวเผา</h2></div>${firingModeToggle(true)}<div class="pwa-handoff-note"><b>⚙️ ระบบรับเข้าสต๊อกอัตโนมัติทำงานอยู่</b><br>${e(info.notice||"ปิดการบันทึกผลเผาผ่านผู้ใช้ชั่วคราว")}</div>${rows.length?`<p class="pwa-workshop-empty">มี ${m(rows.length)} รายการค้างตรวจสอบในประวัติคิวเผา โปรดติดต่อผู้ดูแลก่อนเปิดโหมดบันทึกเอง</p>`:'<p class="pwa-workshop-empty">ไม่มีงานค้างในคิวเผา</p>'}</section>`;
