async function loadHandoff(root,background=false){
  if(background){S.handoffLoading=true;document.body.classList.add("pwa-refreshing");}
  try{
    const r=await S.api.workerPortalOwnerQueue(S.token);
    if(!r.ok)throw Error(r.message||r.error);
    const handoff=r.result||{};
    // The job type is authoritative. Older submission rows may not have a
    // stored route, so normalize them before any card or confirmation renders.
    (handoff.cards||[]).forEach(card=>{
      if(!/เขียนลาย/.test(String(card.role||"")))return;
      const route=String(card.workType||"").trim()==="เบญจรงค์"?"paint":"fire";
      (card.submissions||[]).forEach(sub=>{sub.writerRoute=route;});
    });
    S.handoff=handoff;S.handoffAt=Date.now();
    if(!root?.isConnected||root.dataset.route!=="workshop")return;
    if(background&&(S.handoffReview||S.handoffConfirm||S.handoffAction||S.handoffSaving))return;
    render(root);
  }catch(x){if(!background)S.toast(`โหลดงานจาก App ช่างไม่สำเร็จ: ${x.message||x}`);}
  finally{if(background){S.handoffLoading=false;document.body.classList.remove("pwa-refreshing");}}
}
