function handoffReviewPicker(){
  const state=S.handoffReviewPicker;if(!state)return "";const {card,sub}=handoffFind(state.jobId,state.submissionId);if(!card||!sub)return "";const data=S.handoff||{},isPo=state.kind==="po",rows=(isPo?data.preorderItems:state.kind==="whiteware"?data.whitewares:data.products)||[],q=String(state.query||"").trim().toLowerCase(),label=x=>isPo?`ลูกค้า ${x.customer||"ไม่ระบุชื่อ"} · ${x.name||""} · ${m(x.qty)} ชิ้น (PO ${x.poNo||""})`:state.kind==="whiteware"?`${x.sku} · ${x.name}${x.size?` · ${x.size}`:""} (เหลือ ${m(x.balance)})`:`${x.code} · ${product(x)}`,key=x=>isPo?`${x.poNo}|||${x.itemId}`:state.kind==="whiteware"?x.sku:x.code,list=rows.filter(x=>!q||label(x).toLowerCase().includes(q)),title=isPo?"เลือก PO ปลายทาง":state.kind==="whiteware"?"เลือกของขาว":"เลือก SKU สินค้าหลังเผา",hint=isPo?"ค้นหาจากชื่อลูกค้า เลข PO หรือชื่อสินค้า แล้วแตะรายการที่ต้องการ":"เริ่มจากรายการที่ใกล้เคียงกับชื่อที่ช่างกรอก; พิมพ์ค้นหาต่อ หรือแสดงทั้งหมดได้หากชื่อไม่ตรง";
  const storeOption=isPo?'<button data-a="chooseHandoffReviewPicker" data-key="">เข้าร้าน (ไม่ผูก PO)</button>':"";
  return `<div class="pwa-workshop-modal pwa-handoff-picker-modal"><section class="pwa-workshop-dialog pwa-handoff-picker"><button class="pwa-dialog-x" data-a="closeHandoffReviewPicker">×</button><h2>${title}</h2><input id="handoffReviewPickerSearch" placeholder="🔍 ${isPo?"ค้นหาลูกค้า เลข PO หรือสินค้า":"พิมพ์ชื่อหรือรหัสเพื่อค้นหา"}" value="${e(state.query||"")}" autocomplete="off"><p class="pwa-handoff-note">${hint}</p><div class="pwa-handoff-picker-list">${storeOption}${list.length?list.map(x=>`<button data-a="chooseHandoffReviewPicker" data-key="${e(key(x))}">${e(label(x))}</button>`).join(""):`<p class="pwa-workshop-empty">ไม่พบรายการที่ใกล้เคียง <button data-a="showAllHandoffReviewPicker">แสดงทุกรายการ</button></p>`}</div><div class="pwa-dialog-actions"><button data-a="closeHandoffReviewPicker">← ย้อนกลับ</button></div></section></div>`;
}
async function saveHandoffFromReview(root,button){
  const card=(S.handoff?.cards||[]).find(x=>x.id===button.dataset.job)||{},sub=(card.submissions||[]).find(x=>x.id===button.dataset.sub)||{},gold=card.role==="วนทอง",writer=/เขียนลาย/.test(card.role||"")||isDailyRole(card.role),paint=writer&&String(card.workType||"").trim()==="เบญจรงค์",draft=handoffReviewDraft(sub.id),pair=String(draft.preorderKey||"").split("|||"),whitewareSku=writer?String(draft.whitewareSku||""):"",finishedSku=gold||paint?"":String(draft.finishedSku||"");
  if(writer&&!whitewareSku)return S.toast("กรุณาเลือกของขาว");if(!gold&&!paint&&!finishedSku&&!pair[0])return S.toast("กรุณาเลือก SKU หรือรายการ PO");S.handoffSaving=true;button.disabled=true;button.textContent="⏳ กำลังยืนยัน...";
  try{const r=await S.api.workerPortalConfirmToFiring(S.token,{submissionId:sub.id,whitewareSku,finishedSku,priceEach:Number(card.priceEach)||0,preorderNo:finishedSku?"":pair[0]||"",preorderItemId:finishedSku?"":pair[1]||""});if(!r.ok||!r.result?.success)throw Error(r.result?.message||r.message||"ยืนยันไม่สำเร็จ");delete S.handoffReviewDrafts[String(sub.id)];S.handoffReview=null;invalidateWages();S.handoffSaving=false;S.handoffDone=handoffDoneInfo(card,sub,r.result.message);render(root);await loadHandoff(root);}catch(error){S.handoffSaving=false;button.disabled=false;button.textContent=gold?"ยืนยันบันทึกค่าแรงวนทอง":"✅ ยืนยันรับรองงาน";S.handoffError=handoffErrorInfo(card,error.message||error);render(root);}
}
export function renderWorkshop(root,api,token,onBack,context={}){if(S.token&&S.token!==token){S.monthGeneration++;clearTimeout(S.monthPrefetchTimer);S.monthRequests={};S.months={};S.monthFetchedAt={};S.monthErrors={};S.daily={};invalidateWages();S.handoff=null;S.data=null;S.tab=savedTab();S.monthKey="";S.localLoaded=false;}S.api=api;S.token=token;S.owner=String(context.displayUser?.name||"");S.back=onBack;S.toast=context.toast||(()=>{});if(!S.day)S.day=today();if(S.step!=="วนทอง"&&S.step!=="รายวัน")S.step="เขียนลาย";if(!S.data){const last=api.lastBootstrap?.("workshopBootstrap",token);if(last?.ok)S.data=last.result||{};}render(root);if(S.tab==="receive")refreshHandoff(root);if(!S.data){load(root);/* the wage summary does not need workshop data: start it in parallel */if(S.tab==="wage")void loadWage(root);return;}load(root,true);loadTabData(root);}
// The page can now open directly on a remembered tab, so fetch that tab's own
// data here; previously only a tab click loaded the wage or daily view.
function loadTabData(root){if(S.tab==="wage")void loadWage(root);else if(S.tab==="daily")loadDay(root);else if(S.tab!=="receive")queueInitialWage(root);}
